public with sharing class TA_Opportunity_CollectForErpSync
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    // Accumulates Ids to sync across all chunks of the current DML operation.
    // Static state is reset by the finalizer at the end of each DML operation.
    @TestVisible
    private static Set<Id> idsToSync = new Set<Id>();

    public static Set<Id> getIdsToSync() {
        return idsToSync;
    }

    public static void reset() {
        idsToSync = new Set<Id>();
    }

    public void afterInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            Opportunity opp = (Opportunity) record;
            if (opp.Id != null) {
                idsToSync.add(opp.Id);
            }
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        for (SObject record : triggerOld) {
            Opportunity oldOpp = (Opportunity) record;
            oldMap.put(oldOpp.Id, oldOpp);
        }
        for (SObject record : triggerNew) {
            Opportunity newOpp = (Opportunity) record;
            Opportunity oldOpp = oldMap.get(newOpp.Id);
            if (oldOpp != null && newOpp.StageName != oldOpp.StageName) {
                idsToSync.add(newOpp.Id);
            }
        }
    }
}
