public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {

    public void execute(FinalizerHandler.Context context) {
        // The framework calls every finalizer at the end of every DML operation,
        // regardless of sObject. Capture whatever was collected for this operation,
        // then reset so a subsequent DML operation starts clean.
        Set<Id> idsToSync = TA_Opportunity_CollectForErpSync.getIdsToSync();

        if (idsToSync == null || idsToSync.isEmpty()) {
            return;
        }

        // Defensive copy before clearing the shared static state.
        Set<Id> idsForJob = new Set<Id>(idsToSync);
        TA_Opportunity_CollectForErpSync.reset();

        // Exactly one job per DML operation, carrying all collected Ids.
        // enqueueJob is not DML, so this respects the "no DML in finalizers" rule.
        System.enqueueJob(new OpportunityErpSyncJob(idsForJob));
    }
}
