public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        for (SObject oldRecord : triggerOld) {
            Opportunity oldOpp = (Opportunity) oldRecord;
            oldMap.put(oldOpp.Id, oldOpp);
        }

        List<Task> tasks = new List<Task>();
        for (SObject newRecord : triggerNew) {
            Opportunity opp = (Opportunity) newRecord;

            // Only act the first time this record is seen in the after-update
            // context of the transaction. The rounding action (Order 20) issues
            // a second update that re-runs every Opportunity after-update action;
            // on that recursive pass the framework has already seen this record,
            // so we skip it and never create a duplicate task.
            Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(opp.Id);
            if (timesSeen != null && timesSeen > 1) {
                continue;
            }

            Opportunity oldOpp = oldMap.get(opp.Id);
            if (oldOpp != null && opp.Amount != oldOpp.Amount) {
                tasks.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = opp.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
