/**
 * Before insert Contact action: when a new contact has an Account and a blank
 * LeadSource, default it to the account's AccountSource.
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact con = (Contact) record;
            if (con.AccountId == null || String.isNotBlank(con.LeadSource)) {
                continue;
            }

            Account acc = accountsById.get(con.AccountId);
            if (acc == null) {
                continue;
            }

            con.LeadSource = acc.AccountSource;
        }
    }
}
